import 'dart:convert';
import 'dart:io';

SecurityContext trustedClientContext() =>
    SecurityContext(withTrustedRoots: true)
      ..setTrustedCertificatesBytes(base64Decode(_caCertificate));

SecurityContext testServerContext() => SecurityContext()
  ..useCertificateChainBytes(base64Decode(_serverCertificate))
  ..usePrivateKeyBytes(base64Decode(_serverPrivateKey));

const _caCertificate =
    '';

const _serverCertificate =
    '';

const _serverPrivateKey =
    '';
